INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-creation', 'es', 'title', 'La Creación');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-creation', 'es', 'description', 'Dios construye todo el universo en 6 días y se toma un día libre. La historia de origen de literalmente todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-adam-eve', 'es', 'title', 'Adán y Eva');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-adam-eve', 'es', 'description', 'Una regla. Tenían una regla. Y ni siquiera pudieron con eso. Los problemas de confianza originales.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cain-abel', 'es', 'title', 'Caín y Abel');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cain-abel', 'es', 'description', 'Los primeros hermanos. Los primeros celos. El primer asesinato. Las cosas se salieron de control rapidísimo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-noah', 'es', 'title', 'El Arca de Noé');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-noah', 'es', 'description', 'Dios reinicia todo el planeta. Un hombre construye un zoológico flotante y sobrevive al apocalipsis.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-babel', 'es', 'title', 'La Torre de Babel');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-babel', 'es', 'description', 'La humanidad se une para llegar al cielo. Dios mezcla sus idiomas y los dispersa por todos lados.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abraham-call', 'es', 'title', 'El Llamado de Abraham');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abraham-call', 'es', 'description', 'Un hombre de 75 años escucha a Dios decir ''deja todo y vete''. Sin mapa. Sin GPS. Solo fe.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abrahams-sister-lie', 'es', 'title', 'La Mentira de la Hermana de Abraham');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abrahams-sister-lie', 'es', 'description', 'Abraham le dice al faraón que su esposa es su hermana para salvar su propio pellejo. No es su mejor momento.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-same-lie-again', 'es', 'title', 'La Misma Mentira, Diferente Rey');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-same-lie-again', 'es', 'description', 'Abraham hace el mismo truco de ''es mi hermana'' con otro rey. Pensarías que aprendería.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gods-promise-of-a-son', 'es', 'title', 'La Promesa de Dios de un Hijo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gods-promise-of-a-son', 'es', 'description', 'Dios promete a una pareja de 100 años que tendrán un bebé. Sara literalmente se ríe en la cara de Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-tired-of-waiting', 'es', 'title', 'Cansados de Esperar');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-tired-of-waiting', 'es', 'description', 'Abraham y Sara se impacientan con la promesa de Dios y tratan de forzarla con Agar. Sale espectacularmente mal.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sodom-and-gomorrah', 'es', 'title', 'Sodoma y Gomorra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sodom-and-gomorrah', 'es', 'description', 'Dos ciudades tan perdidas que Dios hace llover fuego del cielo. Abraham negocia, pero no hay ni 10 personas buenas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-lots-escape-gone-wrong', 'es', 'title', 'La Huida de Lot Sale Mal');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-lots-escape-gone-wrong', 'es', 'description', 'Escapan de la ciudad en llamas, su esposa mira atrás y se convierte en sal, luego las cosas se ponen aún más raras en una cueva.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-of-isaac', 'es', 'title', 'El Nacimiento de Isaac');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-of-isaac', 'es', 'description', 'El bebé milagro finalmente llega. La risa llena la tienda donde la duda vivió durante décadas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abraham-isaac', 'es', 'title', 'Abraham e Isaac');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-abraham-isaac', 'es', 'description', 'Dios le pide a Abraham que sacrifique a su único hijo. La prueba de confianza más intensa de la historia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-isaac-and-rebekah', 'es', 'title', 'Isaac y Rebeca');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-isaac-and-rebekah', 'es', 'description', 'Un sirviente, unos camellos, un pozo y una oración. La relación a larga distancia original funciona perfectamente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-esau', 'es', 'title', 'Jacob y Esaú');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-esau', 'es', 'description', 'Hermanos gemelos, una bendición robada y décadas de rencor. Drama familiar en su máxima expresión.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacobs-ladder', 'es', 'title', 'La Escalera de Jacob');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacobs-ladder', 'es', 'description', 'Huyendo y durmiendo sobre una roca, Jacob sueña con una escalera al cielo y Dios le hace una promesa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-rachel-and-leah', 'es', 'title', 'Jacob, Raquel y Lea');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-rachel-and-leah', 'es', 'description', 'Trabaja 7 años por la chica que ama, lo engañan para casarse con su hermana, luego trabaja 7 más. Triángulo amoroso infernal.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-wrestles-god', 'es', 'title', 'Jacob Lucha con Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacob-wrestles-god', 'es', 'description', 'Una lucha nocturna con un extraño misterioso. Jacob no lo suelta hasta que obtiene una bendición y un nuevo nombre.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-brothers', 'es', 'title', 'José y Sus Hermanos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-brothers', 'es', 'description', 'Sus hermanos lo vendieron como esclavo porque estaban celosos de su atuendo. Sí, un abrigo inició todo esto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-egypt', 'es', 'title', 'José en Egipto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-egypt', 'es', 'description', 'De la cárcel a dirigir todo el país. La transformación definitiva.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-forgives', 'es', 'title', 'José Perdona a Sus Hermanos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joseph-forgives', 'es', 'description', 'Sus hermanos llegan rogando por comida, sin saber que él es básicamente el vicepresidente ahora. La revelación lo es todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacobs-family-moves-to-egypt', 'es', 'title', 'La Familia de Jacob se Muda a Egipto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jacobs-family-moves-to-egypt', 'es', 'description', 'Toda la familia se traslada a Egipto. Lo que empieza como refugio se convierte en una estancia de 400 años que nadie planeó.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-baby-moses', 'es', 'title', 'Bebé Moisés');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-baby-moses', 'es', 'description', 'Su mamá lo escondió en una canasta en el río para salvarle la vida. La hija del faraón lo encontró y lo crió como realeza.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-burning-bush', 'es', 'title', 'La Zarza Ardiente');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-burning-bush', 'es', 'description', 'Moisés ve una zarza en llamas que no se consume. Luego Dios empieza a hablar desde ella. Cambio de carrera a la vista.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ten-plagues', 'es', 'title', 'Las 10 Plagas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ten-plagues', 'es', 'description', 'Dios envió 10 plagas cada vez más locas a Egipto. Ríos de sangre, invasiones de ranas, oscuridad total. El faraón aún dijo que no.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-red-sea', 'es', 'title', 'Cruzando el Mar Rojo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-red-sea', 'es', 'description', 'Atrapados entre el mar y un ejército. Moisés levanta su bastón y el mar se divide en dos. El ejército no lo logra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-bread-from-heaven', 'es', 'title', 'Pan del Cielo, Agua de la Roca');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-bread-from-heaven', 'es', 'description', '¿No hay comida? Dios envía pan del cielo cada mañana. ¿No hay agua? Moisés golpea una roca y sale agua.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ten-commandments', 'es', 'title', 'Los 10 Mandamientos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ten-commandments', 'es', 'description', 'Truenos, fuego y la voz de Dios desde una montaña. Moisés baja con los términos y condiciones definitivos tallados en piedra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-golden-calf', 'es', 'title', 'El Becerro de Oro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-golden-calf', 'es', 'description', 'Moisés se fue 40 días y la gente inmediatamente derritió sus joyas en un dios falso. La audacia fue increíble.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-god-gives-a-second-chance', 'es', 'title', 'Dios Da una Segunda Oportunidad');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-god-gives-a-second-chance', 'es', 'description', 'Después del desastre del becerro de oro, Moisés sube de nuevo a la montaña. Dios renueva el pacto. Su cara literalmente brilla.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-building-gods-tent', 'es', 'title', 'Construyendo la Tienda de Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-building-gods-tent', 'es', 'description', 'Dios da planos para un templo portátil. Cada detalle importa — aquí es donde el cielo se encuentra con la tierra en el desierto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-first-priests', 'es', 'title', 'Los Primeros Sacerdotes');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-first-priests', 'es', 'description', 'Aarón y sus hijos son ordenados. Cae fuego sagrado. Luego dos de ellos hacen lo suyo y les cuesta todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-offerings-and-sacrifices', 'es', 'title', 'Ofrendas y Sacrificios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-offerings-and-sacrifices', 'es', 'description', 'Ofrendas quemadas, ofrendas de grano, ofrendas de paz — Dios crea todo un lenguaje para acercarse a él.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-clean-and-unclean', 'es', 'title', 'Limpio e Impuro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-clean-and-unclean', 'es', 'description', 'Reglas sobre comida, piel, moho y fluidos corporales. Suena raro, pero es Dios enseñándoles que la santidad toca todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-day-of-atonement', 'es', 'title', 'El Día de la Expiación');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-day-of-atonement', 'es', 'description', 'Un día al año, un sacerdote entra en la presencia de Dios para cubrir los pecados de toda la nación. El peso de esto es abrumador.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-real-world-holiness', 'es', 'title', 'Santidad en el Mundo Real');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-real-world-holiness', 'es', 'description', '''Ama a tu prójimo como a ti mismo'' aparece aquí primero. Dios detalla cómo se ven la justicia y la bondad en la vida diaria.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sacred-feasts-and-rhythms', 'es', 'title', 'Fiestas Sagradas y Ritmos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sacred-feasts-and-rhythms', 'es', 'description', 'Pascua, festivales de cosecha y el Día de la Expiación. Dios construye un calendario alrededor de recordar lo que ha hecho.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sabbath-jubilee-and-justice', 'es', 'title', 'Sábado, Jubileo y Justicia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sabbath-jubilee-and-justice', 'es', 'description', 'Cada 7 años, deudas canceladas. Cada 50 años, todo se reinicia. La política económica de Dios es salvaje.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-organizing-the-camp', 'es', 'title', 'Organizando el Campamento');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-organizing-the-camp', 'es', 'description', 'Dos millones de personas en el desierto necesitan estructura. Dios organiza cada tribu alrededor de su presencia en el centro.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-camp-rules-and-the-cloud', 'es', 'title', 'Reglas del Campamento y la Nube');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-camp-rules-and-the-cloud', 'es', 'description', 'Leyes de pureza, trompetas y una nube que les dice cuándo moverse y cuándo quedarse. Dios guía en tiempo real.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-complaining-craving-and-chaos', 'es', 'title', 'Quejas, Antojos y Caos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-complaining-craving-and-chaos', 'es', 'description', 'Están hartos del maná y quieren carne. Dios envía codornices — tantas que se enferman. Ten cuidado con lo que deseas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-12-spies-and-a-40-year-detour', 'es', 'title', '12 Espías y un Desvío de 40 Años');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-12-spies-and-a-40-year-detour', 'es', 'description', 'Envían 12 espías a la tierra prometida. 10 regresan aterrados, 2 dicen ''vamos.'' El miedo gana, y les cuesta 40 años.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-rebellion-and-the-earth-opens', 'es', 'title', 'Rebelión y la Tierra se Abre');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-rebellion-and-the-earth-opens', 'es', 'description', 'Coré desafía la autoridad de Moisés. El suelo literalmente se abre y se traga a los rebeldes. Dios no juega.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-snakes-water-and-the-long-road', 'es', 'title', 'Serpientes, Agua y el Largo Camino');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-snakes-water-and-the-long-road', 'es', 'description', 'Más quejas, serpientes venenosas, una serpiente de bronce en un palo, y Moisés pierde la calma con una roca.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-new-census-a-new-start', 'es', 'title', 'Un Nuevo Censo, un Nuevo Comienzo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-new-census-a-new-start', 'es', 'description', 'La vieja generación se ha ido. Un nuevo censo cuenta a un nuevo pueblo listo para finalmente entrar en la tierra prometida.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-make-your-promises-count', 'es', 'title', 'Haz que tus Promesas Cuenten');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-make-your-promises-count', 'es', 'description', 'Leyes sobre votos y ofrendas. Dios toma en serio tu palabra — no hagas promesas que no vas a cumplir.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-talking-donkey-and-a-hired-prophet', 'es', 'title', 'Un Burro que Habla y un Profeta Contratado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-talking-donkey-and-a-hired-prophet', 'es', 'description', 'Un profeta es contratado para maldecir a Israel, pero su burro ve un ángel y empieza a hablar. No puedes inventar esto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-when-curses-wont-stick', 'es', 'title', 'Cuando las Maldiciones no Pegan');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-when-curses-wont-stick', 'es', 'description', 'Balaam intenta maldecir a Israel tres veces. Cada vez, salen bendiciones en su lugar. El enemigo cambia a una táctica más sucia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-battle-against-midian', 'es', 'title', 'La Batalla Contra Madián');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-battle-against-midian', 'es', 'description', 'Se hace justicia sobre Madián por desviar a Israel. La guerra en el mundo antiguo era brutal y decisiva.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-dont-get-comfortable-too-early', 'es', 'title', 'No te Pongas Cómodo Demasiado Pronto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-dont-get-comfortable-too-early', 'es', 'description', 'Dos tribus quieren asentarse al este del Jordán. Moisés casi pierde la calma — no puedes rendirte antes de cruzar la meta.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-wandering', 'es', 'title', 'Vagando por el Desierto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-wandering', 'es', 'description', '40 años de caminata porque no pudieron confiar en Dios. El viaje por carretera más largo del mundo con las peores vibras.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-what-kind-of-leaders-god-wants', 'es', 'title', 'Qué Tipo de Líderes Quiere Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-what-kind-of-leaders-god-wants', 'es', 'description', 'Reyes, sacerdotes, profetas — Dios establece la descripción del trabajo. El poder debe estar atado a la Escritura y la humildad.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-rules-for-war', 'es', 'title', 'Reglas para la Guerra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-rules-for-war', 'es', 'description', 'Incluso en la batalla, hay límites. Protege a los vulnerables, cuida los árboles frutales, ofrece paz primero.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-law-for-messy-lives', 'es', 'title', 'Ley para Vidas Complicadas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-law-for-messy-lives', 'es', 'description', 'Asesinato, matrimonio, propiedad perdida, hijos tercos — Dios tiene algo que decir sobre todo. La santidad se vuelve práctica.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-community-standards', 'es', 'title', 'Estándares Comunitarios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-community-standards', 'es', 'description', 'Honestidad en el tribunal, límites en el castigo, cuidado de los trabajadores. El amor del pacto se parece a una comunidad que protege a sus más débiles.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-one-god-one-place', 'es', 'title', 'Un Dios, Un Lugar de Adoración');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-one-god-one-place', 'es', 'description', 'No hay santuarios en cada colina. Un nombre, un altar, un Dios. La identidad comienza con a quién adoras y cómo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-what-god-really-wants', 'es', 'title', 'Lo que Dios Realmente Quiere');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-what-god-really-wants', 'es', 'description', 'No solo rituales — lealtad a nivel del corazón. Ámalo, camina en sus caminos, sirve con todo lo que tienes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-dont-let-success-ruin-you', 'es', 'title', 'No Dejes que el Éxito te Arruine');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-dont-let-success-ruin-you', 'es', 'description', 'Cuando las bendiciones lleguen, no olvides quién te las dio. La gratitud es la barandilla contra la arrogancia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-remember-where-you-started', 'es', 'title', 'Recuerda de Dónde Empezaste');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-remember-where-you-started', 'es', 'description', 'Eras esclavo. No eras nadie. La memoria es la mejor armadura contra el orgullo y el camino más corto hacia la gratitud.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cancel-debts-set-people-free', 'es', 'title', 'Cancelar Deudas, Liberar a la Gente');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cancel-debts-set-people-free', 'es', 'description', 'Cada 7 años, borrón y cuenta nueva. La generosidad no es opcional, es como la comunidad se mantiene unida.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-ultimate-choice', 'es', 'title', 'La Elección Definitiva');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-ultimate-choice', 'es', 'description', 'Bendición o maldición, vida o muerte. Dios pone ambas opciones sobre la mesa y dice elige.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cities-of-refuge', 'es', 'title', 'Ciudades de Refugio');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cities-of-refuge', 'es', 'description', 'Refugios seguros para asesinos accidentales. Incluso la justicia antigua tenía matices: la intención importa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-setting-boundaries', 'es', 'title', 'Estableciendo Límites');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-setting-boundaries', 'es', 'description', 'Líneas de propiedad y juegos de poder. A Dios le importan los límites, la honestidad y cumplir tu palabra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-fair-play-and-fair-trade', 'es', 'title', 'Juego Limpio y Comercio Justo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-fair-play-and-fair-trade', 'es', 'description', 'Balanzas honestas, trato justo, nada de trampas en los negocios o el culto. La integridad en las pequeñas cosas importa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-moses-farewell-address', 'es', 'title', 'Discurso de Despedida de Moisés');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-moses-farewell-address', 'es', 'description', 'Una canción, una bendición sobre cada tribu, una última mirada desde una montaña. Las palabras finales del mayor profeta.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-choose-life-or-death', 'es', 'title', 'Elige Vida o Muerte');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-choose-life-or-death', 'es', 'description', 'La elección está cerca de ti, en tu boca y en tu corazón. Dios les ruega que elijan la vida.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-blessings-and-curses', 'es', 'title', 'Bendiciones y Maldiciones');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-blessings-and-curses', 'es', 'description', 'Obedece y prospera, desobedece y todo se desmorona. Moisés expone los dos caminos con brutal claridad.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-warning-song', 'es', 'title', 'La Canción de Advertencia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-warning-song', 'es', 'description', 'Moisés escribe una canción prediciendo exactamente cómo Israel se equivocará. Es una advertencia disfrazada de poesía.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-moses-final', 'es', 'title', 'Los Días Finales de Moisés');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-moses-final', 'es', 'description', 'Los llevó hasta allí, pero nunca pudo entrar. Ve la tierra prometida desde una montaña y muere.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joshua-takes-command', 'es', 'title', 'Josué Toma el Mando');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joshua-takes-command', 'es', 'description', 'Nuevo líder, mismo Dios. Josué toma el relevo, envía espías, y una prostituta llamada Rahab los esconde en su techo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-crossing-the-jordan', 'es', 'title', 'Cruzando el Jordán');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-crossing-the-jordan', 'es', 'description', 'Los sacerdotes pisan el río desbordado y se detiene. Caminan sobre tierra seca y apilan piedras para recordar.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jericho', 'es', 'title', 'Josué y Jericó');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jericho', 'es', 'description', 'Camina alrededor de la ciudad 7 días, toca trompetas, grita. Las murallas se derrumban. Estrategia militar: confiar en Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-achans-hidden-sin', 'es', 'title', 'El Pecado Oculto de Acán');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-achans-hidden-sin', 'es', 'description', 'Un hombre roba botín prohibido y lo esconde bajo su tienda. Israel pierde la siguiente batalla por eso.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-gibeonite-trick', 'es', 'title', 'El Truco de los Gabaonitas y el Sol se Detiene');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-gibeonite-trick', 'es', 'description', 'Un tratado de paz falso engaña a Josué. Luego Dios detiene el sol en el cielo para que Israel gane una batalla. Día salvaje.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-conquering-the-land', 'es', 'title', 'Conquistando la Tierra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-conquering-the-land', 'es', 'description', 'Campaña tras campaña, el mapa se llena. La promesa toma forma una batalla a la vez.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-caleb-claims-his-mountain', 'es', 'title', 'Caleb Reclama su Montaña');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-caleb-claims-his-mountain', 'es', 'description', '85 años y sigue en pie de lucha. Caleb dice ''dame la colina con los gigantes'' y la toma.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-claim-your-inheritance', 'es', 'title', 'Reclama tu Herencia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-claim-your-inheritance', 'es', 'description', 'La tierra está dividida, pero algunas tribus son perezosas para reclamarla. No te conformes con tiendas cuando Dios prometió territorio.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-safe-cities-sacred-spaces', 'es', 'title', 'Ciudades Seguras, Espacios Sagrados');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-safe-cities-sacred-spaces', 'es', 'description', 'Se asignan ciudades de refugio. Las ciudades levitas están esparcidas por la tierra. Justicia y adoración por todas partes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-altar-that-almost-started-a-war', 'es', 'title', 'El Altar que Casi Inicia una Guerra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-altar-that-almost-started-a-war', 'es', 'description', 'Dos tribus y media construyen un altar y el resto de Israel casi entra en guerra civil por ello. Hablarlo los salva.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joshuas-final-challenge', 'es', 'title', 'El Último Desafío de Josué');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-joshuas-final-challenge', 'es', 'description', '''Elijan hoy a quién van a servir.'' Josué traza una línea y reta a Israel a comprometerse.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-cycle-of-disobedience', 'es', 'title', 'El Ciclo de la Desobediencia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-cycle-of-disobedience', 'es', 'description', 'Pecado, sufrimiento, clamor, rescate, repetir. Israel cae en un patrón que define toda una era.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-deborah-and-jael', 'es', 'title', 'Débora y la Estaca de la Tienda');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-deborah-and-jael', 'es', 'description', 'Una jueza lidera a Israel a la batalla. Luego otra mujer termina la guerra con una estaca de tienda. No las subestimes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gideon-vs-the-midianites', 'es', 'title', 'Gedeón vs. los Madianitas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gideon-vs-the-midianites', 'es', 'description', 'Dios reduce el ejército de Gedeón de 32,000 a 300. Antorchas, jarras y trompetas contra un ejército masivo. A Dios le encantan las probabilidades imposibles.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-when-victory-goes-to-your-head', 'es', 'title', 'Cuando la Victoria se te Sube a la Cabeza');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-when-victory-goes-to-your-head', 'es', 'description', 'Gedeón gana pero hace un ídolo con el oro. La victoria sin humildad se amarga rápido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-bramble-king', 'es', 'title', 'El Rey Zarza');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-bramble-king', 'es', 'description', 'Abimelec asesina a 70 hermanos para ser rey. Una parábola sobre una zarza predice su caída. El ego destruye.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jephthahs-reckless-vow', 'es', 'title', 'El Voto Imprudente de Jefté');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jephthahs-reckless-vow', 'es', 'description', 'Un guerrero rudo hace un voto que no puede retractar. Le cuesta lo que más ama.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-samson', 'es', 'title', 'Sansón y Dalila');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-samson', 'es', 'description', 'El hombre más fuerte tenía una debilidad: una mujer que le preguntó su secreto tres veces y aún así se lo contó.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-everyone-did-what-they-wanted', 'es', 'title', 'Todos Hacían lo que Querían');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-everyone-did-what-they-wanted', 'es', 'description', 'Sin rey, sin reglas, puro caos. Israel toca fondo. El horror muestra lo que pasa sin Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-homemade-religion', 'es', 'title', 'Religión Casera');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-homemade-religion', 'es', 'description', 'Un tipo construye su propio santuario, contrata a su propio sacerdote, y toda una tribu lo roba. El culto DIY no lleva a nada bueno.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ruth', 'es', 'title', 'Rut y Noemí');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ruth', 'es', 'description', 'Una viuda extranjera elige la lealtad sobre la comodidad. ''Donde tú vayas, yo iré.'' Su fidelidad lo cambia todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-goliath', 'es', 'title', 'David y Goliat');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-goliath', 'es', 'description', 'Un adolescente con una honda contra un gigante de 9 pies con armadura completa. Todos pensaban que estaba loco. No lo estaba.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sauls-last-stand', 'es', 'title', 'La Última Batalla de Saúl');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sauls-last-stand', 'es', 'description', 'El primer rey cae en batalla. David llora a su enemigo con uno de los lamentos más hermosos jamás escritos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-two-kings-two-armies', 'es', 'title', 'Dos Reyes, Dos Ejércitos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-two-kings-two-armies', 'es', 'description', 'Israel se divide entre David y el hijo de Saúl. Generales rivales, diplomacia arriesgada y una larga lucha por el poder.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-king', 'es', 'title', 'David se Convierte en Rey');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-king', 'es', 'description', 'El joven pastor finalmente toma el trono. Israel se une bajo una corona después de años de guerra civil.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-dances-before-the-ark', 'es', 'title', 'David Baila ante el Arca');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-dances-before-the-ark', 'es', 'description', 'El Arca llega a Jerusalén. David baila sin vergüenza. Su esposa lo observa desde la ventana y lo juzga duramente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gods-promise-to-david', 'es', 'title', 'La Promesa de Dios a David');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gods-promise-to-david', 'es', 'description', 'David quiere construirle una casa a Dios. Dios lo voltea: ''Construiré TU casa. Tu trono durará para siempre.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-kindness-to-mephibosheth', 'es', 'title', 'Bondad hacia Mefiboset');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-kindness-to-mephibosheth', 'es', 'description', 'En el apogeo de su poder, David busca al nieto discapacitado de Saúl, no para matarlo, sino para invitarlo a cenar para siempre.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-bathsheba', 'es', 'title', 'David y Betsabé');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-david-bathsheba', 'es', 'description', 'Incluso el rey más grande cayó duro. Poder, lujuria, un encubrimiento y un asesinato. Luego un profeta entra y lo denuncia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-absaloms-rise', 'es', 'title', 'El Ascenso de Absalón');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-absaloms-rise', 'es', 'description', 'La familia de David se fractura. Violación, venganza, exilio: las consecuencias de Betsabé se extienden por su propia casa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-absaloms-rebellion', 'es', 'title', 'La Rebelión de Absalón');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-absaloms-rebellion', 'es', 'description', 'El propio hijo de David se gana el corazón del pueblo y obliga al rey a huir de su propia capital. Carisma sin carácter.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-fathers-worst-battle', 'es', 'title', 'La Peor Batalla de un Padre');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-fathers-worst-battle', 'es', 'description', 'El ejército de David lucha contra el de Absalón. David gana la guerra pero pierde a su hijo. ''Oh Absalón, mi hijo, mi hijo.'' Devastador.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-broken-return', 'es', 'title', 'El Regreso Quebrado de David');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-broken-return', 'es', 'description', 'El rey regresa a Jerusalén, pero nada es igual. El perdón es complicado y reparar toma más tiempo que destruir.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-last-battles', 'es', 'title', 'Las Últimas Batallas de David');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-last-battles', 'es', 'description', 'Los gigantes caen, las deudas se saldan, y los salmos de agradecimiento cierran una era de guerra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-final-mistake', 'es', 'title', 'El Último Error de David');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-davids-final-mistake', 'es', 'description', 'David ordena un censo por orgullo. Sigue una plaga. Compra una era de trillar que se convierte en el futuro sitio del templo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-solomon', 'es', 'title', 'La Sabiduría de Salomón');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-solomon', 'es', 'description', 'Dios dice ''pide lo que quieras.'' Salomón elige sabiduría. Luego lo demuestra de inmediato con la decisión más loca de todas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-elijah-on-mount-carmel', 'es', 'title', 'Elías en el Monte Carmelo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-elijah-on-mount-carmel', 'es', 'description', 'Un profeta contra 450 profetas de Baal. Construyen altares, llaman al fuego. Solo un Dios responde. Elías no se inmuta.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-kingdom-splits', 'es', 'title', 'El Reino se Divide');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-kingdom-splits', 'es', 'description', 'El hijo de Salomón ignora el consejo sabio y se aferra a un gobierno duro. Una nación se convierte en dos por una decisión tonta.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-kings-who-copied-the-worst', 'es', 'title', 'Reyes que Copiaron lo Peor');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-kings-who-copied-the-worst', 'es', 'description', 'Un rey malo tras otro copia los pecados de los anteriores. La religión cosmética no puede curar la podredumbre profunda.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-decay-coups-and-leprosy', 'es', 'title', 'Decadencia, Golpes de Estado y Lepra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-decay-coups-and-leprosy', 'es', 'description', 'La corrupción interna invita al desastre externo. La monarquía se pudre lentamente desde adentro.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-manasseh-hits-reverse', 'es', 'title', 'Manasés Pone Marcha Atrás');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-manasseh-hits-reverse', 'es', 'description', 'Un hijo deshace las reformas de su padre y lleva a la nación a su peor bajón espiritual. Una generación puede deshacer décadas de progreso.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-josiah-finds-the-lost-book', 'es', 'title', 'Josías Encuentra el Libro Perdido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-josiah-finds-the-lost-book', 'es', 'description', 'Los trabajadores encuentran el Libro de la Ley enterrado en los escombros del templo. Cuando el rey lo escucha, rasga sus vestiduras y reforma todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-josiahs-last-battle', 'es', 'title', 'La Última Batalla de Josías');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-josiahs-last-battle', 'es', 'description', 'El rey del avivamiento libra una última guerra. Los altares son destruidos, los corazones son llamados a casa, pero el reloj avanza para Judá.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-hezekiahs-extra-years', 'es', 'title', 'Los Años Extra de Ezequías');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-hezekiahs-extra-years', 'es', 'description', 'Dios le da a Ezequías 15 años más, luego él lo arruina mostrando sus tesoros a las personas equivocadas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-one-angel-one-army-destroyed', 'es', 'title', 'Un Ángel, Un Ejército Destruido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-one-angel-one-army-destroyed', 'es', 'description', '185,000 soldados asirios rodean Jerusalén. Ezequías ora. Un ángel. Una noche. Todo el ejército desaparece por la mañana.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-hezekiah-vs-the-empire', 'es', 'title', 'Ezequías vs. el Imperio');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-hezekiah-vs-the-empire', 'es', 'description', 'Un rey fiel enfrenta a la máquina de guerra asiria. Llegan cartas de intimidación. Las extiende ante Dios y ora.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-northern-kingdom-falls', 'es', 'title', 'El Reino del Norte Cae');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-northern-kingdom-falls', 'es', 'description', 'Siglos de malos reyes pasan factura. Asiria conquista Israel y dispersa las 10 tribus. Nunca regresan.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jerusalem-burns', 'es', 'title', 'Jerusalén Arde');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jerusalem-burns', 'es', 'description', 'Babilonia rompe las murallas y quema el templo hasta los cimientos. El pueblo es llevado al exilio. Todo se ha perdido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-daniel-lions', 'es', 'title', 'Daniel y el Foso de los Leones');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-daniel-lions', 'es', 'description', 'Lo lanzaron a un foso de leones porque no dejaba de orar. Los leones no lo tocaron.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-esther', 'es', 'title', 'Ester Salva a su Pueblo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-esther', 'es', 'description', 'Una reina judía secreta arriesga todo para detener un genocidio. Entra sin invitación ante el rey. Energía de personaje principal total.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jonah', 'es', 'title', 'Jonás y la Ballena');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jonah', 'es', 'description', 'Dios dijo ve a la izquierda. Jonás fue a la derecha. Un pez gigante se lo tragó por 3 días. Lección aprendida a la mala.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-angel-visits-zechariah', 'es', 'title', 'Un Ángel Visita a Zacarías');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-angel-visits-zechariah', 'es', 'description', 'Un sacerdote mayor recibe la visita de un ángel prometiendo un bebé milagro. Duda y pierde la voz por 9 meses.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-angel-visits-mary', 'es', 'title', 'Un Ángel Visita a María');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-angel-visits-mary', 'es', 'description', 'A una adolescente le dicen que llevará al hijo de Dios. Ella dice que sí. José casi se va. El embarazo más importante de la historia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-of-john-the-baptist', 'es', 'title', 'El Nacimiento de Juan el Bautista');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-of-john-the-baptist', 'es', 'description', 'Llega el bebé milagro. Zacarías recupera su voz y profetiza. Nace el precursor de Jesús.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-jesus', 'es', 'title', 'El Nacimiento de Jesús');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-birth-jesus', 'es', 'description', 'Una adolescente, sin lugar en la posada, un bebé nace en un establo con animales. Ángeles cantan a pastores. Navidad pero de verdad.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-simeon-and-anna', 'es', 'title', 'Simeón y Ana en el Templo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-simeon-and-anna', 'es', 'description', 'Dos creyentes ancianos esperaron toda su vida para ver al Mesías. Reconocen a un bebé en los brazos de sus padres.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-wise-men', 'es', 'title', 'Los Reyes Magos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-wise-men', 'es', 'description', 'Eruditos seguidores de estrellas del este traen oro, incienso y mirra. El rey Herodes no está contento con la competencia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-flight-to-egypt', 'es', 'title', 'Huida a Egipto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-flight-to-egypt', 'es', 'description', 'Un ángel advierte a José en un sueño. La familia huye a Egipto en la noche. Herodes mata a todos los bebés varones en Belén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-boy-jesus-at-the-temple', 'es', 'title', 'El Niño Jesús en el Templo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-boy-jesus-at-the-temple', 'es', 'description', 'Jesús de doce años se queda en el templo, debatiendo con eruditos. Sus padres se asustan. Él dice ''Estoy en la casa de mi Padre.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptist-preaches', 'es', 'title', 'Juan el Bautista Predica');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptist-preaches', 'es', 'description', 'Un hombre salvaje en el desierto vistiendo pelo de camello, comiendo langostas, gritando ''arrepiéntanse.'' Está preparando el camino para alguien más grande.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-declares-the-lamb', 'es', 'title', 'Juan Declara ''El Cordero de Dios''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-declares-the-lamb', 'es', 'description', 'Juan ve venir a Jesús y dice ''Miren — el Cordero de Dios.'' Un profeta que señala más allá de sí mismo al que importa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-baptism', 'es', 'title', 'Jesús es Bautizado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-baptism', 'es', 'description', 'Jesús entra al río Jordán y el cielo se abre. Una paloma desciende. Dios dice ''ese es mi hijo'' en voz alta.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-40-days-in-the-desert', 'es', 'title', '40 Días en el Desierto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-40-days-in-the-desert', 'es', 'description', 'Hambriento y solo, Jesús enfrenta los tres mejores trucos del diablo. Los derriba todos con las Escrituras.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-meeting-the-first-disciples', 'es', 'title', 'Conociendo a los Primeros Discípulos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-meeting-the-first-disciples', 'es', 'description', 'Invitaciones simples — ''ven y verás'' — cambian el curso de la historia. Pescadores dejan sus redes y siguen.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-first-miracles', 'es', 'title', 'Agua en Vino');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-first-miracles', 'es', 'description', 'El primer milagro de Jesús ocurre en una fiesta de bodas porque su mamá básicamente lo presionó. Icónico.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-nicodemus-comes-at-night', 'es', 'title', 'Nicodemo Viene de Noche');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-nicodemus-comes-at-night', 'es', 'description', 'Un líder religioso se cuela a ver a Jesús después del anochecer. ''Debes nacer de nuevo.'' La conversación que lo explica todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-flips-tables', 'es', 'title', 'Jesús Vuelca Mesas en el Templo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-flips-tables', 'es', 'description', 'Jesús entra al templo, lo ve convertido en un mercado, y empieza a volcar mesas. Nadie lo detiene.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptists-last-words', 'es', 'title', 'Las Últimas Palabras de Juan el Bautista');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptists-last-words', 'es', 'description', 'Mientras su propio seguimiento disminuye, Juan dice ''Él debe crecer, yo debo menguar.'' Un profeta que conocía su papel.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-healing-at-the-pool', 'es', 'title', 'Sanación en el Estanque de Betesda');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-healing-at-the-pool', 'es', 'description', 'Un hombre espera 38 años junto a un estanque esperando sanación. Jesús se acerca y dice ''¿quieres ser sano?'' Una palabra y listo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-miraculous-catch', 'es', 'title', 'La Pesca Milagrosa');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-miraculous-catch', 'es', 'description', 'Pescadores profesionales no pescan nada en toda la noche. Jesús dice inténtalo de nuevo. Las redes casi se rompen por la captura.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-casting-out-an-evil-spirit', 'es', 'title', 'Expulsando un Espíritu Maligno');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-casting-out-an-evil-spirit', 'es', 'description', 'En la sinagoga, un demonio le grita a Jesús. Una orden y se va. La multitud está asombrada — ¿quién ES este tipo?');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-mother-in-law-healed', 'es', 'title', 'La Suegra de Pedro Sanada');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-mother-in-law-healed', 'es', 'description', 'Jesús toca su mano, la fiebre se va, y ella inmediatamente se levanta y empieza a servir la cena. La noticia corre rápido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-touching-the-leper', 'es', 'title', 'Tocando al Leproso');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-touching-the-leper', 'es', 'description', 'Nadie toca a los leprosos. Jesús extiende su mano. ''Quiero. Sé limpio.'' El marginado es restaurado.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-through-the-roof', 'es', 'title', 'A Través del Techo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-through-the-roof', 'es', 'description', 'Cuatro amigos no pueden pasar entre la multitud, así que abren el techo y bajan a su amigo paralizado hasta Jesús. Eso es amistad.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-matthew-leaves-everything', 'es', 'title', 'Mateo Deja Todo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-matthew-leaves-everything', 'es', 'description', 'Un odiado recaudador de impuestos escucha ''sígueme'', se aleja de la mesa del dinero y organiza una cena para Jesús con todos sus amigos dudosos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-sabbath-showdowns', 'es', 'title', 'Los Enfrentamientos del Sábado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-sabbath-showdowns', 'es', 'description', 'Jesús sana en sábado y los líderes religiosos pierden la cabeza. Las reglas se hicieron para la gente, no al revés.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-picking-the-twelve', 'es', 'title', 'Eligiendo a los Doce');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-picking-the-twelve', 'es', 'description', 'Después de una noche de oración, Jesús elige a su equipo — pescadores, un recaudador de impuestos, un zelote y un traidor. Elecciones interesantes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-centurions-faith', 'es', 'title', 'La Fe del Centurión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-centurions-faith', 'es', 'description', 'Un soldado romano dice ''solo di la palabra y mi siervo será sanado.'' Jesús se queda impresionado — este forastero tiene más fe que Israel.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-widows-son-lives-again', 'es', 'title', 'El Hijo de la Viuda Vive de Nuevo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-widows-son-lives-again', 'es', 'description', 'Una procesión fúnebre. Una madre afligida. Jesús toca el ataúd, dice ''levántate,'' y el muerto se sienta. La multitud se vuelve loca.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-deaf-ears-opened', 'es', 'title', 'Oídos Sordos Abiertos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-deaf-ears-opened', 'es', 'description', 'Un hombre sordo con problemas de habla se encuentra con Jesús. Oídos abiertos, lengua suelta, y la multitud no puede dejar de hablar de ello.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-stops-a-storm', 'es', 'title', 'Jesús Detiene una Tormenta');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-stops-a-storm', 'es', 'description', 'Olas chocando, barco hundiéndose, discípulos gritando. Jesús se despierta de una siesta y le dice a la tormenta que se calle. Y lo hace.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-legion-and-the-pigs', 'es', 'title', 'Legión y los Cerdos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-legion-and-the-pigs', 'es', 'description', 'Un hombre poseído por miles de demonios vive en un cementerio. Jesús lo libera en una frase. Los demonios van a los cerdos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jairus-daughter-and-the-bleeding-woman', 'es', 'title', 'La Hija de Jairo y la Mujer con Hemorragia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jairus-daughter-and-the-bleeding-woman', 'es', 'description', 'Un padre desesperado y una mujer atrevida. Ambos necesitan un milagro. Ambos lo obtienen. La fe interrumpe la muerte.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-healing-the-officials-son', 'es', 'title', 'Sanando al Hijo del Oficial');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-healing-the-officials-son', 'es', 'description', 'Un oficial real le suplica a Jesús que sane a su hijo moribundo. Jesús dice ''ve a casa, tu hijo está bien.'' Y lo está.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-demons-and-accusations', 'es', 'title', 'Demonios y Acusaciones');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-demons-and-accusations', 'es', 'description', 'Jesús expulsa un demonio y los fariseos lo acusan de trabajar para Satanás. Jesús desmantela su lógica en segundos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptist-beheaded', 'es', 'title', 'Juan el Bautista Decapitado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-john-the-baptist-beheaded', 'es', 'description', 'Una fiesta de cumpleaños, un baile, y una petición horripilante. El mayor profeta pierde la cabeza por un rencor.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-feeds-5000', 'es', 'title', 'Jesús Alimenta a 5,000');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-feeds-5000', 'es', 'description', '5 panes, 2 peces, 5,000 personas hambrientas. Lo hizo funcionar. Y hubo sobras.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-walks-water', 'es', 'title', 'Jesús Camina sobre el Agua');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-walks-water', 'es', 'description', 'En medio de una tormenta. Discípulos en pánico. Luego ven a alguien caminando sobre las olas hacia ellos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-feeding-4000', 'es', 'title', 'Jesús Alimenta a 4,000');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-feeding-4000', 'es', 'description', 'Multitud diferente, misma compasión. Unos pocos panes, unos pocos peces, miles alimentados. El pan se convierte en un tema recurrente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-bread-of-life', 'es', 'title', 'Pan de Vida');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-bread-of-life', 'es', 'description', 'Después del milagro de la comida, Jesús dice ''YO SOY el pan de vida.'' La multitud quería comida. Él se ofreció a sí mismo. Muchos se alejan.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-purity-debate', 'es', 'title', 'El Debate de la Pureza');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-purity-debate', 'es', 'description', 'Los fariseos se obsesionan con los rituales de lavado de manos. Jesús dice que no es lo que entra en ti lo que te contamina, sino lo que sale de tu corazón.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-mothers-desperate-faith', 'es', 'title', 'La Fe Desesperada de una Madre');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-a-mothers-desperate-faith', 'es', 'description', 'Una mujer sirofenicia le suplica a Jesús que sane a su hija. Él la pone a prueba. Ella responde con uno de los mejores comebacks de la Biblia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-big-confession', 'es', 'title', 'La Gran Confesión de Pedro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-big-confession', 'es', 'description', '''¿Quién dices que soy?'' Pedro lo clava: ''Eres el Cristo''. Luego Jesús suelta la primera predicción de su muerte.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-transfiguration', 'es', 'title', 'La Transfiguración');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-transfiguration', 'es', 'description', 'Jesús lleva a tres discípulos a una montaña. Su rostro brilla como el sol. Aparecen Moisés y Elías. Pedro quiere construir tiendas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-boy-with-a-demon', 'es', 'title', 'El Niño con un Demonio');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-boy-with-a-demon', 'es', 'description', 'Los discípulos no pueden sanar a un niño poseído por un demonio. Jesús lo hace al instante y dice ''este tipo requiere oración y ayuno''.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-predicts-his-death', 'es', 'title', 'Jesús Predice Su Muerte');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-predicts-his-death', 'es', 'description', 'Jesús les dice a los discípulos exactamente lo que viene: traición, muerte, resurrección. No entienden. Lo dice tres veces.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-fish-with-a-coin', 'es', 'title', 'El Pez con una Moneda');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-fish-with-a-coin', 'es', 'description', 'Los recaudadores de impuestos vienen a preguntar. Jesús le dice a Pedro que pesque un pez: habrá una moneda en su boca. Y la hay. Cuenta pagada.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-festival-showdown', 'es', 'title', 'El Enfrentamiento en el Festival');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-festival-showdown', 'es', 'description', 'Jesús aparece en la Fiesta de los Tabernáculos y las multitudes están divididas: ¿profeta, engañador o Mesías? La tensión es palpable.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-born-blind-now-sees', 'es', 'title', 'Nacido Ciego, Ahora Ve');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-born-blind-now-sees', 'es', 'description', 'Jesús sana a un hombre ciego de nacimiento. Los fariseos lo interrogan sin parar. Su respuesta es simple: ''Era ciego. Ahora veo.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-good-shepherd', 'es', 'title', 'El Buen Pastor');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-good-shepherd', 'es', 'description', '''Yo soy el buen pastor. El buen pastor da su vida por las ovejas.'' Jesús define el liderazgo por el sacrificio.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sending-out-72', 'es', 'title', 'Enviando a 72 Misioneros');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-sending-out-72', 'es', 'description', 'Jesús envía a 72 seguidores delante de él en parejas. Regresan asombrados: incluso los demonios les obedecen.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-good-samaritan', 'es', 'title', 'El Buen Samaritano');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-good-samaritan', 'es', 'description', 'Un hombre es robado y dejado por muerto. Personas religiosas pasan de largo. El despreciado forastero se detiene a ayudar. ''¿Quién fue el vecino?''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-mary-and-martha', 'es', 'title', 'María y Marta');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-mary-and-martha', 'es', 'description', 'Una hermana está ocupada en la cocina, la otra está sentada a los pies de Jesús. Marta se queja. Jesús se pone del lado de María.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-teaching-them-to-pray', 'es', 'title', 'Enseñándoles a Orar');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-teaching-them-to-pray', 'es', 'description', '''Señor, enséñanos a orar.'' Jesús les da la oración más simple y poderosa de la historia. Luego cuenta una historia sobre la persistencia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-casting-out-demons-and-taking-heat', 'es', 'title', 'Expulsando Demonios y Aguantando Críticas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-casting-out-demons-and-taking-heat', 'es', 'description', 'Jesús expulsa a un demonio. Algunos dicen que está usando el poder de Satanás. Jesús desmantela la acusación y advierte sobre casas vacías.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-calling-out-the-pharisees', 'es', 'title', 'Llamando la Atención a los Fariseos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-calling-out-the-pharisees', 'es', 'description', 'Jesús acepta una invitación a cenar y luego absolutamente destroza a los fariseos en su cara. La hipocresía queda expuesta en la mesa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-woman-at-the-well', 'es', 'title', 'La Mujer en el Pozo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-woman-at-the-well', 'es', 'description', 'Una marginada samaritana se encuentra con Jesús en un pozo. Él sabe todo sobre ella. Ella se convierte en la primera evangelista.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-lazarus-lives-again', 'es', 'title', 'Lázaro Vive de Nuevo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-lazarus-lives-again', 'es', 'description', 'Muerto cuatro días, sellado en una tumba. Jesús llora, luego grita ''¡Lázaro, sal fuera!'' Y lo hace. El mic drop definitivo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-go-ahead-throw-a-stone', 'es', 'title', 'Adelante, Lanza una Piedra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-go-ahead-throw-a-stone', 'es', 'description', 'Una mujer sorprendida en adulterio es arrastrada ante Jesús. ''Que el que esté sin pecado tire primero.'' Uno por uno, se van.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-wedding-feast-parables', 'es', 'title', 'Las Parábolas del Banquete de Bodas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-wedding-feast-parables', 'es', 'description', 'Se envían invitaciones a los VIPs. Todos ponen excusas. Así que el anfitrión invita a todos de las calles en su lugar.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-narrow-door', 'es', 'title', 'La Puerta Estrecha');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-narrow-door', 'es', 'description', '''Esfuércense por entrar por la puerta estrecha.'' Muchos lo intentarán y fallarán. La urgencia resuena — no esperes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-counting-the-cost', 'es', 'title', 'Contando el Costo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-counting-the-cost', 'es', 'description', 'Seguir a Jesús no es casual. Cuenta el costo primero. No busca fans — quiere gente que cargue una cruz.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-prodigal-son', 'es', 'title', 'El Hijo Pródigo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-prodigal-son', 'es', 'description', 'Tomó su herencia, la despilfarró toda, y regresó arrastrándose para comer comida de cerdos. Su papá le hizo una fiesta de todos modos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-shrewd-manager', 'es', 'title', 'El Administrador Astuto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-shrewd-manager', 'es', 'description', 'Un administrador a punto de ser despedido hace tratos con los deudores de su jefe. Jesús alaba el ingenio. ¿Qué?');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-rich-man-and-lazarus', 'es', 'title', 'El Rico y Lázaro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-rich-man-and-lazarus', 'es', 'description', 'Un hombre rico ignora a un mendigo en su puerta. Ambos mueren. La inversión en el otro lado es permanente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-zacchaeus-climbs-a-tree', 'es', 'title', 'Zaqueo Sube a un Árbol');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-zacchaeus-climbs-a-tree', 'es', 'description', 'Un cobrador de impuestos bajito y rico sube a un sicómoro para ver a Jesús. Jesús lo ve y se invita a cenar. Todo cambia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-cursed-fig-tree', 'es', 'title', 'La Higuera Maldita y la Furia en el Templo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-cursed-fig-tree', 'es', 'description', 'Jesús maldice una higuera sin fruto y limpia el templo de comerciantes. Ambos actos dicen lo mismo: da fruto o serás cortado.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-palm-sunday', 'es', 'title', 'Domingo de Ramos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-palm-sunday', 'es', 'description', 'Jesús entra en Jerusalén montado en un burro. Las multitudes agitan palmas y gritan ''¡Hosanna!'' El rey llega — pero no como nadie esperaba.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-caesars-coin', 'es', 'title', 'La Moneda del César');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-caesars-coin', 'es', 'description', 'Intentan atrapar a Jesús con una pregunta política. Él pide una moneda. ''Den al César lo que es del César, y a Dios lo que es de Dios.'' Fin del asunto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-faith-figs-and-loaded-questions', 'es', 'title', 'Fe, Higueras y Preguntas Trucadas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-faith-figs-and-loaded-questions', 'es', 'description', 'Los líderes religiosos lanzan trampa tras trampa a Jesús. Él responde a cada una y devuelve el golpe más fuerte.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-marriage-and-the-afterlife', 'es', 'title', 'Matrimonio y la Vida Después de la Muerte');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-marriage-and-the-afterlife', 'es', 'description', 'Los saduceos creen que tienen a Jesús con un acertijo sobre el matrimonio después de la muerte. Él lo desarma en una frase.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-greatest-commandment', 'es', 'title', 'El Mandamiento Más Grande');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-greatest-commandment', 'es', 'description', '''Ama a Dios con todo. Ama a tu prójimo como a ti mismo.'' Toda la ley y los profetas dependen de estas dos líneas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-whose-son-is-the-messiah', 'es', 'title', '¿De Quién es Hijo el Mesías?');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-whose-son-is-the-messiah', 'es', 'description', 'Jesús plantea a los fariseos un acertijo sobre el hijo de David. Nadie puede responder. Él revela que el Mesías es más grande de lo que imaginaban.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-signs-of-the-end', 'es', 'title', 'Señales del Fin');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-signs-of-the-end', 'es', 'description', 'En el Monte de los Olivos, Jesús describe el fin del mundo — guerras, terremotos, engaños. ''Mantente listo. No sabes el día.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-plot-against-jesus', 'es', 'title', 'La Conspiración Contra Jesús');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-plot-against-jesus', 'es', 'description', 'Los líderes religiosos ya han tenido suficiente. Comienzan a conspirar en secreto para arrestar y matar a Jesús antes de que termine el festival.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-judas-makes-a-deal', 'es', 'title', 'Judas Hace un Trato');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-judas-makes-a-deal', 'es', 'description', 'Treinta monedas de plata. Ese es el precio que Judas pone a Jesús. Camina hacia los sacerdotes y ofrece entregarlo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-anointed-at-bethany', 'es', 'title', 'Ungido en Betania');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-anointed-at-bethany', 'es', 'description', 'Una mujer derrama perfume caro sobre Jesús. Los discípulos dicen que es un desperdicio. Jesús dice que lo está preparando para el entierro.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-last-supper', 'es', 'title', 'La Última Cena');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-last-supper', 'es', 'description', 'Su última comida con sus 12 amigos más cercanos. El pan y el vino se convierten en su cuerpo y sangre. Uno de ellos está a punto de traicionarlo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gethsemane', 'es', 'title', 'Getsemaní');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-gethsemane', 'es', 'description', '''Aparta de mí esta copa. Pero no se haga mi voluntad — sino la tuya.'' En una tristeza aplastante, Jesús elige la obediencia sobre la fuga.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-arrested-in-the-garden', 'es', 'title', 'Arrestado en el Jardín');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-arrested-in-the-garden', 'es', 'description', 'Un beso de Judas. Antorchas y espadas. Pedro blande una espada y corta una oreja. Jesús la sana y se entrega.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-before-the-sanhedrin', 'es', 'title', 'Ante el Sanedrín');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-before-the-sanhedrin', 'es', 'description', 'Testigos falsos, preguntas cargadas y una respuesta honesta: ''Yo soy.'' El sumo sacerdote rasga sus vestiduras. Culpable de blasfemia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-three-denials', 'es', 'title', 'Las Tres Negaciones de Pedro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-three-denials', 'es', 'description', '''No lo conozco.'' Tres veces. Luego canta el gallo. Pedro recuerda y se rompe en llanto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-before-pilate', 'es', 'title', 'Jesús Ante Pilato');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-jesus-before-pilate', 'es', 'description', 'Pilato no encuentra culpa en él. La multitud grita por crucifixión. Se lava las manos y entrega a Jesús.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-crucifixion', 'es', 'title', 'La Crucifixión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-crucifixion', 'es', 'description', 'Se burlaron de él, lo golpearon y lo clavaron en una cruz. El cielo se oscureció. Dijo ''Consumado es'' y entregó su espíritu.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-buried-in-a-borrowed-tomb', 'es', 'title', 'Enterrado en una Tumba Prestada');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-buried-in-a-borrowed-tomb', 'es', 'description', 'José de Arimatea baja el cuerpo, lo envuelve en lino y lo coloca en su propia tumba nueva. Una piedra sella la entrada.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-resurrection', 'es', 'title', 'La Resurrección');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-resurrection', 'es', 'description', 'Tres días después, la tumba está vacía. Está vivo. Todo lo que dijo era verdad. El mejor regreso de la historia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-road-to-emmaus', 'es', 'title', 'El Camino a Emaús');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-road-to-emmaus', 'es', 'description', 'Dos discípulos desconsolados caminan a casa. Un extraño se une a ellos y les explica las Escrituras. Cuando parte el pan, se dan cuenta: es Jesús.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-doubting-thomas', 'es', 'title', 'Tomás el Incrédulo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-doubting-thomas', 'es', 'description', '''A menos que ponga mi dedo en los agujeros de los clavos, no creeré.'' Jesús aparece y dice ''adelante.'' Tomás cae de rodillas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-great-commission', 'es', 'title', 'La Gran Comisión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-great-commission', 'es', 'description', '''Vayan y hagan discípulos de todas las naciones.'' Jesús da la declaración de misión final antes de dejar la tierra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-ascension', 'es', 'title', 'La Ascensión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-ascension', 'es', 'description', 'Jesús lleva a sus discípulos a una colina, los bendice y asciende al cielo. Dos ángeles dicen ''volverá.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pentecost', 'es', 'title', 'Pentecostés');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pentecost', 'es', 'description', 'El Espíritu Santo llega como fuego y viento. Todos empiezan a hablar idiomas que nunca aprendieron. La iglesia nace.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-beautiful-gate-miracle', 'es', 'title', 'El Milagro de la Puerta Hermosa');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-beautiful-gate-miracle', 'es', 'description', 'Un mendigo discapacitado le pide dinero a Pedro. Pedro dice ''No tengo dinero, pero tengo algo mejor.'' El hombre camina.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ananias-and-sapphira', 'es', 'title', 'Ananías y Safira');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-ananias-and-sapphira', 'es', 'description', 'Una pareja miente sobre su donación a la iglesia. Ambos caen muertos. Dios no está jugando con falsos en la iglesia primitiva.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-stephen-the-first-martyr', 'es', 'title', 'Esteban, el Primer Mártir');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-stephen-the-first-martyr', 'es', 'description', 'Un hombre lleno de fe y fuego predica la verdad. Lo apedrean hasta la muerte. Los perdona mientras muere.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-church-scatters', 'es', 'title', 'La Iglesia se Dispersa y Felipe');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-church-scatters', 'es', 'description', 'La persecución dispersa a los creyentes por todas partes. Felipe termina bautizando a un funcionario etíope en un camino desértico. El evangelio se expande.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-saul-meets-jesus', 'es', 'title', 'Saulo se Encuentra con Jesús en el Camino');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-saul-meets-jesus', 'es', 'description', 'Un cazador de cristianos queda cegado por una luz. Jesús dice ''¿por qué me persigues?'' Saulo se convierte en Pablo. El mayor giro de 180 en la historia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-miracles', 'es', 'title', 'Los Milagros de Pedro en Lida y Joppe');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-miracles', 'es', 'description', 'Pedro sana a un hombre paralítico y resucita a una mujer muerta. Los apóstoles caminan en el mismo poder que tenía Jesús.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cornelius-and-the-vision', 'es', 'title', 'Cornelio y la Visión del Lienzo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-cornelius-and-the-vision', 'es', 'description', 'Dios envía a Pedro una visión de comida prohibida y dice ''come.'' El mensaje: la salvación ya no es solo para los judíos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-antioch-church', 'es', 'title', 'La Iglesia de Antioquía');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-antioch-church', 'es', 'description', 'Una iglesia diversa se lanza en Antioquía. Por primera vez, los seguidores de Jesús son llamados ''cristianos.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-james-killed-peter-escapes', 'es', 'title', 'Jacobo Muerto, Pedro Escapa');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-james-killed-peter-escapes', 'es', 'description', 'El rey Herodes ejecuta a Jacobo. Arresta a Pedro también, pero un ángel lo saca de la prisión en medio de la noche.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pauls-first-journey', 'es', 'title', 'El Primer Viaje Misionero de Pablo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pauls-first-journey', 'es', 'description', 'Pablo y Bernabé se lanzan a la aventura. Nuevas iglesias surgen, viejos hábitos resisten, y el evangelio llega a donde nunca antes había estado.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-jerusalem-council', 'es', 'title', 'El Concilio de Jerusalén');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-jerusalem-council', 'es', 'description', 'La iglesia primitiva debate la gran pregunta: ¿los no judíos deben seguir la ley judía? Deciden que todo es por gracia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-earthquake-at-philippi', 'es', 'title', 'Terremoto en Filipos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-earthquake-at-philippi', 'es', 'description', 'Pablo y Silas están en prisión, cantando himnos a medianoche. Un terremoto abre las puertas. El carcelero se convierte.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-thessalonica-riot-and-berea', 'es', 'title', 'Disturbio en Tesalónica y Eruditos de Berea');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-thessalonica-riot-and-berea', 'es', 'description', 'Una ciudad se amotina, la siguiente verifica las Escrituras a diario. Dos recepciones muy diferentes para el mismo mensaje.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-athens-the-unknown-god', 'es', 'title', 'Atenas: El Dios Desconocido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-athens-the-unknown-god', 'es', 'description', 'Pablo encuentra un altar etiquetado ''Al Dios Desconocido''. Él dice ''déjenme presentarlo''. La filosofía se encuentra con la revelación.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-riot-in-ephesus', 'es', 'title', 'Disturbio en Éfeso y la Hoguera');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-riot-in-ephesus', 'es', 'description', 'Los creyentes queman sus libros de magia valorados en millones. Los plateros se amotinan porque están perdiendo dinero. El poder enfrenta al lucro.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-eutychus-falls-out-a-window', 'es', 'title', 'Eutico Se Cae de una Ventana');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-eutychus-falls-out-a-window', 'es', 'description', 'Pablo predica tanto que un joven se duerme, se cae de una ventana del tercer piso y muere. Pablo lo revive.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-farewell-at-miletus', 'es', 'title', 'Despedida en Mileto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-farewell-at-miletus', 'es', 'description', 'Pablo se despide de los líderes de la iglesia en Mileto. Hay lágrimas en la orilla. Sabe que no los verá de nuevo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-arrested-at-the-temple', 'es', 'title', 'Arrestado en el Templo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-arrested-at-the-temple', 'es', 'description', 'Pablo visita el templo en Jerusalén y una multitud lo arrastra afuera. Los soldados romanos le salvan la vida. Comienzan los juicios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-trials-before-governors', 'es', 'title', 'Juicios Ante Gobernadores');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-trials-before-governors', 'es', 'description', 'Pablo es pasado de un oficial romano a otro. Cada uno no encuentra culpa, pero nadie lo libera. Apela a César.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-shipwreck-and-malta', 'es', 'title', 'Naufragio y Malta');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-shipwreck-and-malta', 'es', 'description', 'Una tormenta brutal, 14 días perdidos en el mar, el barco se rompe. Todos llegan a la orilla. Una serpiente muerde a Pablo. Él la sacude.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-paul-under-house-arrest', 'es', 'title', 'Pablo Bajo Arresto Domiciliario');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-paul-under-house-arrest', 'es', 'description', 'Encadenado a un guardia romano en una habitación alquilada, Pablo sigue predicando. Las cadenas no pueden detener la palabra.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-james-writes-to-the-church', 'es', 'title', 'Santiago Escribe a la Iglesia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-james-writes-to-the-church', 'es', 'description', 'Sabiduría práctica para creyentes dispersos. La fe sin acción está muerta. Controla tu lengua. Ayuda a los pobres. Sin excusas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-final-letter', 'es', 'title', 'La Última Carta de Pedro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-peters-final-letter', 'es', 'description', 'Un apóstol envejecido advierte sobre falsos maestros y recuerda a la iglesia: él VIO a Jesús transfigurado en esa montaña. Esto no es ficción.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pauls-last-letter', 'es', 'title', 'La Última Carta de Pablo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-pauls-last-letter', 'es', 'description', 'Desde una prisión romana, Pablo escribe a Timoteo una última vez. ''He peleado la buena batalla. He terminado la carrera.''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-johns-exile-and-revelation', 'es', 'title', 'El Exilio de Juan y la Revelación');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-johns-exile-and-revelation', 'es', 'description', 'Exiliado en una isla, el último apóstol vivo recibe una visión del cielo, el juicio y el fin de todas las cosas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-new-heaven-and-new-earth', 'es', 'title', 'El Nuevo Cielo y la Nueva Tierra');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'story', 'st-the-new-heaven-and-new-earth', 'es', 'description', 'Dios seca cada lágrima. No más muerte, dolor ni llanto. Todo es hecho nuevo. La historia termina donde comenzó: Dios con su pueblo.');

